impl FitUnsupervised for NakagamiHmm {
    type Fitted = FittedNakagamiHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedNakagamiHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        if t_len == 0 {
            return ctx.finish(FittedNakagamiHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                m: Vector::filled(k, 1.0),
                omega: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut mpar = Vector::from_iter((0..k).map(|j| 1.0 + 0.4 * j as f64));
        let mut omega = Vector::from_iter((0..k).map(|j| 1.0 + j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedNakagamiHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                m: mpar.clone(),
                omega: omega.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy2 = 0.0_f64;
                let mut wy4 = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 0.0 {
                        continue;
                    }
                    let y2 = y * y;
                    wsum += fb.gamma[t][j];
                    wy2 += fb.gamma[t][j] * y2;
                    wy4 += fb.gamma[t][j] * y2 * y2;
                }
                if wsum > 1e-12 {
                    let om = (wy2 / wsum).max(1e-8);
                    omega[j] = om;
                    let v = (wy4 / wsum - om * om).max(1e-8);
                    mpar[j] = (om * om / v).clamp(0.25, 40.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedNakagamiHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            m: mpar.clone(),
            omega: omega.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedNakagamiHmm {
            labels,
            start,
            trans,
            m: mpar,
            omega,
            loglik,
        })
    }
}

