impl FitUnsupervised for MakehamHmm {
    type Fitted = FittedMakehamHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedMakehamHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) <= 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!("MakehamHmm skipped {n_skip} non-positive observations"))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedMakehamHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                a: Vector::filled(k, 0.2),
                b: Vector::filled(k, 0.08),
                lam: Vector::filled(k, 0.1),
                loglik: f64::NAN,
            });
        }
        let mut a = Vector::from_iter((0..k).map(|j| 0.15 + 0.1 * j as f64));
        let b = Vector::from_iter((0..k).map(|j| 0.06 + 0.03 * j as f64));
        let lam = Vector::from_iter((0..k).map(|j| 0.08 + 0.04 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedMakehamHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                a: a.clone(),
                b: b.clone(),
                lam: lam.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * y;
                }
                if wsum > 1e-12 {
                    let m = (wy / wsum).max(0.2);
                    a[j] = (0.6 / m).clamp(0.02, 2.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedMakehamHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            a: a.clone(),
            b: b.clone(),
            lam: lam.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedMakehamHmm {
            labels,
            start,
            trans,
            a,
            b,
            lam,
            loglik,
        })
    }
}

