impl FittedFoldedTHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.loc.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_folded_t(y, self.loc[j], self.scale[j], self.nu[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedFoldedTHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for FoldedTHmm {
    type Fitted = FittedFoldedTHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedFoldedTHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let nu = Vector::from_iter((0..k).map(|j| 4.0 + 4.0 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) < 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!("FoldedTHmm skipped {n_skip} negative observations"))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedFoldedTHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                loc: Vector::from_iter((0..k).map(|j| 1.0 + j as f64)),
                scale: Vector::filled(k, 1.0),
                nu,
                loglik: f64::NAN,
            });
        }
        let mut loc = Vector::from_iter((0..k).map(|j| 1.5 + 2.0 * j as f64));
        let mut scale = Vector::filled(k, 1.0);
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedFoldedTHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                loc: loc.clone(),
                scale: scale.clone(),
                nu: nu.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * y;
                }
                if wsum > 1e-12 {
                    loc[j] = (wy / wsum).max(0.25);
                    let mut w2 = 0.0_f64;
                    for t in 0..t_len {
                        let y = x.get(t, 0);
                        if y.is_finite() && y >= 0.0 {
                            let e = y - loc[j];
                            w2 += fb.gamma[t][j] * e * e;
                        }
                    }
                    scale[j] = (w2 / wsum).max(COV_FLOOR).sqrt();
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedFoldedTHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            loc: loc.clone(),
            scale: scale.clone(),
            nu: nu.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedFoldedTHmm {
            labels,
            start,
            trans,
            loc,
            scale,
            nu,
            loglik,
        })
    }
}

