impl FitUnsupervised for DiscreteLaplaceHmm {
    type Fitted = FittedDiscreteLaplaceHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedDiscreteLaplaceHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        if t_len == 0 {
            return ctx.finish(FittedDiscreteLaplaceHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                p: Vector::filled(k, 0.4),
                loglik: f64::NAN,
            });
        }
        let mut p = Vector::from_iter((0..k).map(|j| 0.3 + 0.2 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedDiscreteLaplaceHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                p: p.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * y.round().abs();
                }
                if wsum > 1e-12 {
                    let m = (wy / wsum).max(1e-6);
                    p[j] = ((-1.0 + (1.0 + m * m).sqrt()) / m).clamp(1e-3, 0.99);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedDiscreteLaplaceHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            p: p.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedDiscreteLaplaceHmm {
            labels,
            start,
            trans,
            p,
            loglik,
        })
    }
}

fn log_inv_gompertz(y: f64, eta: f64, beta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || eta <= 0.0 || beta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let z = beta / y;
    if !z.is_finite() || z > 20.0 {
        return f64::NEG_INFINITY;
    }
    let ez = z.exp();
    if !ez.is_finite() {
        return f64::NEG_INFINITY;
    }
    eta.ln() + beta.ln() - 2.0 * y.ln() + z - eta * (ez - 1.0)
}

fn log_inv_nakagami(y: f64, m: f64, omega: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || m <= 0.0 || omega <= 0.0 {
        return f64::NEG_INFINITY;
    }
    std::f64::consts::LN_2 + m * m.ln()
        - crate::special::ln_gamma(m)
        - m * omega.ln()
        - (2.0 * m + 1.0) * y.ln()
        - m / (omega * y * y)
}

fn log_zilog(y: f64, pi: f64, p: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || pi <= 0.0 || pi >= 1.0 || p <= 0.0 || p >= 1.0 {
        return f64::NEG_INFINITY;
    }
    if y.abs() < 1e-12 {
        pi.ln()
    } else {
        (1.0 - pi).ln() + log_logarithmic(y, p)
    }
}

fn log_power_lindley(y: f64, theta: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || alpha <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let ya = y.powf(alpha);
    if !ya.is_finite() || ya > 80.0 {
        return f64::NEG_INFINITY;
    }
    2.0 * theta.ln() - (theta + 1.0).ln() + (1.0 + ya).ln() + alpha.ln() + (alpha - 1.0) * y.ln()
        - theta * ya
}

fn log_discrete_lindley(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let yr = y.round().max(0.0);
    2.0 * theta.ln() + (1.0 + yr).ln() - (yr + 2.0) * (1.0 + theta).ln()
}

/// Inverse-Gompertz lifetime HMM on \((0,\infty)\).
///
/// Shape \(\beta\) is a hyperparameter, not identification `p`. Distinct from
/// [`GompertzHmm`] (linear hazard) and [`ChenHmm`] (\(x^\beta\) in the
/// cumulative hazard).
