impl FitUnsupervised for MarshallOlkinExponentialHmm {
    type Fitted = FittedMarshallOlkinExponentialHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedMarshallOlkinExponentialHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let alpha = Vector::from_iter((0..k).map(|j| 0.25 + 0.45 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) <= 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "MarshallOlkinExponentialHmm skipped {n_skip} non-positive observations"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedMarshallOlkinExponentialHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                lam: Vector::filled(k, 0.4),
                alpha,
                loglik: f64::NAN,
            });
        }
        let mut lam = Vector::from_iter((0..k).map(|j| 0.2 + 0.15 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedMarshallOlkinExponentialHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                lam: lam.clone(),
                alpha: alpha.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let aj: f64 = alpha[j];
                let mut lj = lam[j];
                for _ in 0..5 {
                    let mut g = 0.0_f64;
                    let mut gp = 0.0_f64;
                    for t in 0..t_len {
                        let y = x.get(t, 0);
                        if !y.is_finite() || y <= 0.0 {
                            continue;
                        }
                        let w = fb.gamma[t][j];
                        let e = (-lj * y).exp();
                        let den = 1.0 - aj * e;
                        if den <= 1e-10 {
                            continue;
                        }
                        let num = aj * y * e;
                        g += w * (1.0 / lj - y - 2.0 * num / den);
                        gp += w
                            * (-1.0 / (lj * lj)
                                - 2.0 * (aj * y * y * e * (den - aj * e)) / (den * den));
                    }
                    if gp.abs() > 1e-12 {
                        lj = (lj - g / gp).clamp(1e-4, 10.0);
                    }
                }
                lam[j] = lj;
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedMarshallOlkinExponentialHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            lam: lam.clone(),
            alpha: alpha.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedMarshallOlkinExponentialHmm {
            labels,
            start,
            trans,
            lam,
            alpha,
            loglik,
        })
    }
}

