impl FitUnsupervised for AlphaMuHmm {
    type Fitted = FittedAlphaMuHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedAlphaMuHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let alpha = Vector::from_iter((0..k).map(|j| 1.5 + j as f64));
        let mu = Vector::from_iter((0..k).map(|j| 1.4 + 0.8 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) <= 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!("AlphaMuHmm skipped {n_skip} non-positive observations"))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedAlphaMuHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                alpha,
                mu,
                rhat: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut rhat = Vector::from_iter((0..k).map(|j| 1.0 + 0.5 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedAlphaMuHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                alpha: alpha.clone(),
                mu: mu.clone(),
                rhat: rhat.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wpow = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wpow += fb.gamma[t][j] * y.powf(alpha[j]);
                }
                if wsum > 1e-12 && wpow > 0.0 {
                    rhat[j] = (wpow / wsum).powf(1.0 / alpha[j]).clamp(1e-3, 40.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedAlphaMuHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            alpha: alpha.clone(),
            mu: mu.clone(),
            rhat: rhat.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedAlphaMuHmm {
            labels,
            start,
            trans,
            alpha,
            mu,
            rhat,
            loglik,
        })
    }
}

/// Yacoub \(\kappa\)-\(\mu\) fading HMM (\(I_{\mu-1/2}\); \(\mu\in\{1.5,2.5\}\)).
///
/// \(\kappa>0\) and half-integer \(\mu\neq 1\) (Rice) are hyperparameters, not
/// identification `p`. Distinct from [`RiceHmm`], [`HoytHmm`], and
/// [`NakagamiHmm`] (\(\kappa=0\)).
#[derive(Clone, Debug)]
pub struct KappaMuHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for KappaMuHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl KappaMuHmm {
    /// `k`-state \(\kappa\)-\(\mu\) HMM.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(&mut self, x: &Matrix, session: &Session) -> Result<Qualified<FittedKappaMuHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted \(\kappa\)-\(\mu\) HMM.
#[derive(Clone, Debug)]
pub struct FittedKappaMuHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Ratio \(\kappa_j>0\).
    pub kappa: Vector,
    /// Half-integer \(\mu_j\in\{1.5,2.5\}\).
    pub mu: Vector,
    /// Second moments \(\Omega_j\).
    pub omega: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedKappaMuHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.omega.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_kappa_mu(y, self.kappa[j], self.mu[j], self.omega[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedKappaMuHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for KappaMuHmm {
    type Fitted = FittedKappaMuHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedKappaMuHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let kappa = Vector::from_iter((0..k).map(|j| 0.6 + 1.2 * j as f64));
        let mu = Vector::from_iter((0..k).map(|j| 1.5 + j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) <= 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!("KappaMuHmm skipped {n_skip} non-positive observations"))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedKappaMuHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                kappa,
                mu,
                omega: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut omega = Vector::from_iter((0..k).map(|j| 1.4 + 0.8 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedKappaMuHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                kappa: kappa.clone(),
                mu: mu.clone(),
                omega: omega.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wx2 = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wx2 += fb.gamma[t][j] * y * y;
                }
                if wsum > 1e-12 {
                    omega[j] = (wx2 / wsum).max(COV_FLOOR);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedKappaMuHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            kappa: kappa.clone(),
            mu: mu.clone(),
            omega: omega.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedKappaMuHmm {
            labels,
            start,
            trans,
            kappa,
            mu,
            omega,
            loglik,
        })
    }
}

