impl FittedDiscreteDagumHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_disc_dagum(y, self.scale[j], self.a[j], self.p[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedDiscreteDagumHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for DiscreteDagumHmm {
    type Fitted = FittedDiscreteDagumHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedDiscreteDagumHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let kst = self.n_states.max(1);
        let a = Vector::from_iter((0..kst).map(|j| 1.6 + 0.5 * j as f64));
        let p = Vector::from_iter((0..kst).map(|j| 2.2 + 0.4 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) < 1.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "DiscreteDagumHmm skipped {n_skip} observations below 1"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedDiscreteDagumHmm {
                labels: empty_labels(0),
                start: init_start(kst),
                trans: init_trans(kst),
                scale: Vector::filled(kst, 3.0),
                a,
                p,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..kst).map(|j| 2.0 + 1.5 * j as f64));
        let mut start = init_start(kst);
        let mut trans = init_trans(kst);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedDiscreteDagumHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                a: a.clone(),
                p: p.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..kst {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 1.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * y;
                }
                if wsum > 1e-12 {
                    scale[j] = (wy / wsum).clamp(0.5, 20.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], kst, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..kst)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedDiscreteDagumHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            scale: scale.clone(),
            a: a.clone(),
            p: p.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedDiscreteDagumHmm {
            labels,
            start,
            trans,
            scale,
            a,
            p,
            loglik,
        })
    }
}

fn log_unit_chen(y: f64, lam: f64, beta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || lam <= 0.0 || beta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_chen(y / (1.0 - y), lam, beta) - 2.0 * (1.0 - y).ln()
}

fn log_beta_exp(y: f64, rate: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || rate <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let surv = (-rate * y).exp().max(1e-15);
    let cdf = (1.0 - surv).max(1e-15);
    rate.ln() - rate * y + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_gamma(y: f64, shape: f64, rate: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape <= 0.0 || rate <= 0.0 || alpha <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = crate::special::gamma_p(shape, rate * y);
    if !cdf.is_finite() || cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    alpha.ln() + log_gamma_emit(y, shape, rate) + (alpha - 1.0) * cdf.ln()
}

fn log_kuma_lomax(y: f64, scale: f64, shape: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || shape <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 + y / scale).powf(-shape);
    let cdf = (1.0 - surv).max(1e-15);
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_lomax(y, scale, shape) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_lomax(y: f64, scale: f64, shape: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 || shape <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let surv = |x: f64| {
        if x < 0.0 {
            1.0
        } else {
            (1.0 + x / scale).powf(-shape)
        }
    };
    let p = (surv(kk) - surv(kk + 1.0)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit-Chen HMM on \((0,1)\) (Chen on \(u=x/(1-x)\), \(\beta\neq 1\)).
