fn half_cauchy_cdf(y: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 {
        return 0.0;
    }
    ((2.0 / std::f64::consts::PI) * (y / scale).atan()).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_half_cauchy(y: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_half_cauchy(y / (1.0 - y), scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_half_cauchy(y: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = half_cauchy_cdf(y, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_half_cauchy(y, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_half_cauchy(y: f64, scale: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || alpha <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = half_cauchy_cdf(y, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    alpha.ln() + log_half_cauchy(y, scale) + (alpha - 1.0) * cdf.ln()
}

fn log_kuma_half_cauchy(y: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = half_cauchy_cdf(y, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_half_cauchy(y, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_half_cauchy(y: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let p = (half_cauchy_cdf(kk + 1.0, scale) - half_cauchy_cdf(kk, scale)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}


