fn log_inv_maxwell(y: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_maxwell(1.0 / y, scale) - 2.0 * y.ln()
}

fn inv_maxwell_cdf(y: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 {
        return 0.0;
    }
    (1.0 - maxwell_cdf(1.0 / y, scale)).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_inv_maxwell(y: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_inv_maxwell(y / (1.0 - y), scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_inv_maxwell(y: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_maxwell_cdf(y, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_inv_maxwell(y, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_inv_maxwell(y: f64, scale: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || alpha <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_maxwell_cdf(y, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    alpha.ln() + log_inv_maxwell(y, scale) + (alpha - 1.0) * cdf.ln()
}

fn log_kuma_inv_maxwell(y: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_maxwell_cdf(y, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_inv_maxwell(y, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_inv_maxwell(y: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let p = (inv_maxwell_cdf(kk + 1.0, scale) - inv_maxwell_cdf(kk, scale)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit inverse-Maxwell HMM on \((0,1)\) (inverse-Maxwell on \(u=x/(1-x)\)).
///
/// Scale is not identification `p`. Distinct from [`UnitMaxwellHmm`]
