fn rig_cdf(y: f64, mu: f64, lambda: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || mu <= 0.0 || lambda <= 0.0 {
        return 0.0;
    }
    let r = (lambda / y).sqrt();
    let z1 = r * (y / mu - 1.0);
    let z2 = -r * (y / mu + 1.0);
    let tilt = (2.0 * lambda / mu).exp();
    let second = if tilt.is_finite() {
        tilt * crate::special::norm_cdf(z2)
    } else {
        0.0
    };
    (crate::special::norm_cdf(z1) - second).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_rig(y: f64, mu: f64, lambda: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || mu <= 0.0 || lambda <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_rig(y / (1.0 - y), mu, lambda) - 2.0 * (1.0 - y).ln()
}

fn log_beta_rig(y: f64, mu: f64, lambda: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || mu <= 0.0 || lambda <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = rig_cdf(y, mu, lambda);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_rig(y, mu, lambda) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_rig(y: f64, mu: f64, lambda: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || mu <= 0.0 || lambda <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = rig_cdf(y, mu, lambda);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_rig(y, mu, lambda) + (power - 1.0) * cdf.ln()
}

fn log_kuma_rig(y: f64, mu: f64, lambda: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || mu <= 0.0 || lambda <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = rig_cdf(y, mu, lambda);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_rig(y, mu, lambda) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_rig(y: f64, mu: f64, lambda: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || mu <= 0.0 || lambda <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let p = (rig_cdf(kk + 1.0, mu, lambda) - rig_cdf(kk, mu, lambda)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit RIG HMM on \((0,1)\) (Wald companion \(x^{-1/2}\) on \(u=x/(1-x)\)).
