/// Fitted KumaraswamyHyperexponentialHmm.
#[derive(Clone, Debug)]
pub struct FittedKumaraswamyHyperexponentialHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// First rates \(\lambda_{1,j}\).
    pub scale: Vector,
    /// Pinned second rates.
    pub rate2: Vector,
    /// Pinned mixture weights (not identification `p`).
    pub mix: Vector,
    /// First extra shapes \(a_j\neq 1\).
    pub a: Vector,
    /// Second extra shapes \(b_j\neq 1\).
    pub b: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedKumaraswamyHyperexponentialHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_kuma_hx(y, self.mix[j], self.scale[j], self.rate2[j], self.a[j], self.b[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

