fn erlang_cdf(y: f64, shape: f64, rate: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape < 1.0 || rate <= 0.0 {
        return 0.0;
    }
    let p = crate::special::gamma_p(shape.round().max(1.0), rate * y);
    if !p.is_finite() {
        return 0.0;
    }
    p.clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_erl(y: f64, shape: f64, rate: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || shape < 1.0 || rate <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_erlang(y / (1.0 - y), shape, rate) - 2.0 * (1.0 - y).ln()
}

fn log_beta_erl(y: f64, shape: f64, rate: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape < 1.0 || rate <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = erlang_cdf(y, shape, rate);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_erlang(y, shape, rate) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_erl(y: f64, shape: f64, rate: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape < 1.0 || rate <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = erlang_cdf(y, shape, rate);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_erlang(y, shape, rate) + (power - 1.0) * cdf.ln()
}

fn log_kuma_erl(y: f64, shape: f64, rate: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape < 1.0 || rate <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = erlang_cdf(y, shape, rate);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_erlang(y, shape, rate) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_erl(y: f64, shape: f64, rate: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || shape < 1.0 || rate <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let p = (erlang_cdf(kk + 1.0, shape, rate) - erlang_cdf(kk, shape, rate)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit Erlang HMM on \((0,1)\) (integer-shape Gamma on \(u=x/(1-x)\)).
