fn xgamma_rate_from_mean(m: f64) -> f64 {
    let m = m.max(1e-3);
    let disc = (m - 1.0) * (m - 1.0) + 8.0 * m;
    (1.0 - m + disc.sqrt()) / (2.0 * m)
}

fn xgamma_cdf(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 {
        return 0.0;
    }
    let surv = (-theta * y).exp() * (1.0 + theta * theta * y / (2.0 * (1.0 + theta)));
    if !surv.is_finite() {
        return 1.0 - 1e-15;
    }
    (1.0 - surv).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_xg(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_xgamma(y / (1.0 - y), theta) - 2.0 * (1.0 - y).ln()
}

fn log_beta_xg(y: f64, theta: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = xgamma_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_xgamma(y, theta) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_xg(y: f64, theta: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = xgamma_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_xgamma(y, theta) + (power - 1.0) * cdf.ln()
}

fn log_kuma_xg(y: f64, theta: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = xgamma_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_xgamma(y, theta) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_xg(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let p = (xgamma_cdf(kk + 1.0, theta) - xgamma_cdf(kk, theta)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit Xgamma HMM on \((0,1)\) (Exp/Gamma(2) mixture on \(u=x/(1-x)\)).
///
/// Rate is free from the Xgamma mean. Distinct from [`UnitGammaHmm`]
