fn shanker_rate_from_mean(m: f64) -> f64 {
    let m = m.max(1e-3);
    let mut lo = 1e-3_f64;
    let mut hi = 20.0_f64;
    for _ in 0..40 {
        let mid = 0.5 * (lo + hi);
        let pred = (mid * mid + 2.0) / (mid * (mid * mid + 1.0));
        if pred > m {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    0.5 * (lo + hi)
}

fn shanker_cdf(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 {
        return 0.0;
    }
    let t2 = theta * theta;
    let surv = (-theta * y).exp() * (1.0 + theta * y / (t2 + 1.0));
    if !surv.is_finite() {
        return 1.0 - 1e-15;
    }
    (1.0 - surv).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_sk(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_shanker(y / (1.0 - y), theta) - 2.0 * (1.0 - y).ln()
}

fn log_beta_sk(y: f64, theta: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = shanker_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_shanker(y, theta) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_sk(y: f64, theta: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = shanker_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_shanker(y, theta) + (power - 1.0) * cdf.ln()
}

fn log_kuma_sk(y: f64, theta: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = shanker_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_shanker(y, theta) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_sk(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let p = (shanker_cdf(kk + 1.0, theta) - shanker_cdf(kk, theta)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit Shanker HMM on \((0,1)\) (Exp/Gamma(2) mix on \(u=x/(1-x)\)).
