fn inv_rayleigh_cdf(y: f64, sigma: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || sigma <= 0.0 {
        return 0.0;
    }
    let f = (-sigma / (2.0 * y * y)).exp();
    if !f.is_finite() {
        return 0.0;
    }
    f.clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_ir(y: f64, sigma: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || sigma <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_inv_rayleigh(y / (1.0 - y), sigma) - 2.0 * (1.0 - y).ln()
}

fn log_beta_ir(y: f64, sigma: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || sigma <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_rayleigh_cdf(y, sigma);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_inv_rayleigh(y, sigma) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_ir(y: f64, sigma: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || sigma <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_rayleigh_cdf(y, sigma);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_inv_rayleigh(y, sigma) + (power - 1.0) * cdf.ln()
}

fn log_kuma_ir(y: f64, sigma: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || sigma <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_rayleigh_cdf(y, sigma);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_inv_rayleigh(y, sigma) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

