fn inv_chen_cdf(y: f64, lam: f64, beta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || beta <= 0.0 {
        return 0.0;
    }
    let yb = (1.0 / y).powf(beta);
    if !yb.is_finite() || yb > 40.0 {
        return 0.0;
    }
    let ey = yb.exp();
    if !ey.is_finite() {
        return 0.0;
    }
    let f = (-lam * (ey - 1.0)).exp();
    if !f.is_finite() {
        return 0.0;
    }
    f.clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_ic(y: f64, lam: f64, beta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || lam <= 0.0 || beta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_inv_chen(y / (1.0 - y), lam, beta) - 2.0 * (1.0 - y).ln()
}

fn log_beta_ic(y: f64, lam: f64, beta: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || beta <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_chen_cdf(y, lam, beta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_inv_chen(y, lam, beta) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_ic(y: f64, lam: f64, beta: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || beta <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_chen_cdf(y, lam, beta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_inv_chen(y, lam, beta) + (power - 1.0) * cdf.ln()
}

fn log_kuma_ic(y: f64, lam: f64, beta: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || beta <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = inv_chen_cdf(y, lam, beta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_inv_chen(y, lam, beta) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

/// Unit inverse-Chen HMM on \((0,1)\) (inverse-Chen on \(u=x/(1-x)\)).
///
/// Scale \(\lambda\) is free from \(\mathbb{E}[e^{U^{-\beta}}-1]\); shape \(\beta\neq 1\) is pinned, not identification `p`. Distinct from [`UnitChenHmm`] and [`InverseChenHmm`] (half-line). Discrete inverse-Chen already exists.
#[derive(Clone, Debug)]
pub struct UnitInverseChenHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitInverseChenHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitInverseChenHmm {
    /// `k`-state UnitInverseChenHmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitInverseChenHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitInverseChenHmm.
#[derive(Clone, Debug)]
pub struct FittedUnitInverseChenHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Rates \(\lambda_j\).
    pub scale: Vector,
    /// Pinned shapes \(\beta_j\neq 1\).
    pub shape: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitInverseChenHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_ic(y, self.scale[j], self.shape[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitInverseChenHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitInverseChenHmm {
    type Fitted = FittedUnitInverseChenHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitInverseChenHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let shape = Vector::from_iter((0..k).map(|j| 0.70 + 0.15 * j as f64));
let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitInverseChenHmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitInverseChenHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 0.12),
                shape,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 0.12 + 0.04 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitInverseChenHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                shape: shape.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wex = 0.0_f64;
                let bj: f64 = shape[j];
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let u = y / (1.0 - y);
                    if !u.is_finite() || u <= 0.0 {
                        continue;
                    }
                    let yb = (1.0 / u).powf(bj);
                    if !yb.is_finite() || yb > 40.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wex += fb.gamma[t][j] * (yb.exp() - 1.0);
                }
                if wsum > 1e-12 && wex > 1e-18 {
                    scale[j] = (wsum / wex).clamp(0.06, 0.22);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitInverseChenHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            scale: scale.clone(),
            shape: shape.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitInverseChenHmm {
            labels,
            start,
            trans,
            scale,
            shape,
            loglik,
        })
    }
}

