                let al: f64 = shape[j];
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 1.0 {
                        continue;
                    }
                    let z = y.round().max(1.0);
                    if !z.is_finite() || z <= 0.0 {
                        continue;
                    }
                    let inv = z.powf(-al);
                    if !inv.is_finite() || inv <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    winv += fb.gamma[t][j] * inv;
                }
