fn exp_power_cdf(y: f64, loc: f64, scale: f64, shape: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 || shape <= 0.0 {
        return 0.0;
    }
    let z = (y - loc) / scale;
    if z.abs() < 1e-15 {
        return 0.5;
    }
    let t = z.abs().powf(shape);
    let g = crate::special::gamma_p(1.0 / shape, t);
    if !g.is_finite() {
        return if z > 0.0 { 1.0 - 1e-15 } else { 0.0 };
    }
    (0.5 + 0.5 * z.signum() * g).clamp(0.0, 1.0 - 1e-15)
}

fn log_folded_exp_power(y: f64, loc: f64, scale: f64, shape: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || shape <= 0.0 {
        return f64::NEG_INFINITY;
    }
    // Asymmetric when μ≠0: f(|X|=y) = f(y)+f(-y).
    logsumexp(&[
        log_exp_power(y, loc, scale, shape),
        log_exp_power(-y, loc, scale, shape),
    ])
}

fn fep_g_cdf(y: f64, loc: f64, scale: f64, shape: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || shape <= 0.0 {
        return 0.0;
    }
    (exp_power_cdf(y, loc, scale, shape) - exp_power_cdf(-y, loc, scale, shape)).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_fep(y: f64, loc: f64, scale: f64, shape: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 || shape <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_folded_exp_power(u, loc, scale, shape) - 2.0 * (1.0 - y).ln()
}

fn log_beta_fep(y: f64, loc: f64, scale: f64, shape: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || shape <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fep_g_cdf(y, loc, scale, shape);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_folded_exp_power(y, loc, scale, shape) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_fep(y: f64, loc: f64, scale: f64, shape: f64, power: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || shape <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fep_g_cdf(y, loc, scale, shape);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_folded_exp_power(y, loc, scale, shape) + (power - 1.0) * cdf.ln()
}

fn log_kuma_fep(y: f64, loc: f64, scale: f64, shape: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || shape <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fep_g_cdf(y, loc, scale, shape);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_folded_exp_power(y, loc, scale, shape) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_fep(y: f64, loc: f64, scale: f64, shape: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 || shape <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = fep_g_cdf(kk, loc, scale, shape);
    let hi = fep_g_cdf(kk + 1.0, loc, scale, shape);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit folded-exponential-power HMM (folded Subbotin on the odds $y/(1-y)$).
///
/// Scale is free from $\exp(\mathbb{E}[\ln U])$; location $\mu\neq 0$ and shape $\beta\notin\{1,2\}$ are pinned, not identification `p`. Distinct from [`ExponentialPowerHmm`] (two-sided), [`FoldedNormalHmm`] ($\beta=2$), and [`FoldedLaplaceHmm`] ($\beta=1$). Fold uses $f(y)+f(-y)$.
#[derive(Clone, Debug)]
pub struct UnitFoldedExponentialPowerHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitFoldedExponentialPowerHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitFoldedExponentialPowerHmm {
    /// `k`-state UnitFoldedExponentialPowerHmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitFoldedExponentialPowerHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitFoldedExponentialPowerHmm.
#[derive(Clone, Debug)]
pub struct FittedUnitFoldedExponentialPowerHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free folded-exponential-power scales from $\exp(\mathbb{E}[\ln Y])$.
    pub scale: Vector,
    /// Pinned pre-fold locations $\mu_j\neq 0$.
    pub loc: Vector,
    /// Pinned exponential-power shapes $\beta_j\notin\{1,2\}$.
    pub shape: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitFoldedExponentialPowerHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_fep(y, self.loc[j], self.scale[j], self.shape[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitFoldedExponentialPowerHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitFoldedExponentialPowerHmm {
    type Fitted = FittedUnitFoldedExponentialPowerHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitFoldedExponentialPowerHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = Vector::from_iter((0..k).map(|j| 0.12 + 0.03 * j as f64));
        let shape = Vector::from_iter((0..k).map(|j| 1.35 + 0.25 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitFoldedExponentialPowerHmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitFoldedExponentialPowerHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 0.85),
                loc,
                shape,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 0.85 + 0.20 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitFoldedExponentialPowerHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                shape: shape.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wln = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let z = y / (1.0 - y);
                    if !z.is_finite() || z <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wln += fb.gamma[t][j] * z.ln();
                }
                if wsum > 1e-12 {
                    let hat = (wln / wsum).exp();
                    if hat.is_finite() && hat > 0.0 {
                        scale[j] = hat.clamp(0.45, 1.80);
                    }
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitFoldedExponentialPowerHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                shape: shape.clone(),
                loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitFoldedExponentialPowerHmm {
            labels,
            start,
            trans,
            scale,
            loc,
            shape,
            loglik,
        })
    }
}

