fn triangular_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let a = loc - scale;
    let b = loc + scale;
    if y <= a {
        return 0.0;
    }
    if y >= b {
        return 1.0 - 1e-15;
    }
    if y <= loc {
        let t = (y - a) / scale;
        (0.5 * t * t).clamp(0.0, 1.0 - 1e-15)
    } else {
        let t = (b - y) / scale;
        (1.0 - 0.5 * t * t).clamp(0.0, 1.0 - 1e-15)
    }
}

fn log_unit_tr(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_triangular(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_tr(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = triangular_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_triangular(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_tr(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = triangular_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_triangular(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_tr(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = triangular_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_triangular(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_tr(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = triangular_cdf(kk, loc, scale);
    let hi = triangular_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

