fn log_cos32(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (1073741824.0 / (300540195.0 * scale)) * c4 * c4 * c4 * c4 * c4 * c4 * c4 * c4;
    dens.max(1e-15).ln()
}

fn cos32_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let th = std::f64::consts::PI * u / 2.0;
    let pi = std::f64::consts::PI;
    (0.5
        + th / pi
        + (16.0 / (17.0 * pi)) * (2.0 * th).sin()
        + (20.0 / (51.0 * pi)) * (4.0 * th).sin()
        + (560.0 / (2907.0 * pi)) * (6.0 * th).sin()
        + (91.0 / (969.0 * pi)) * (8.0 * th).sin()
        + (208.0 / (4845.0 * pi)) * (10.0 * th).sin()
        + (52.0 / (2907.0 * pi)) * (12.0 * th).sin()
        + (1040.0 / (156009.0 * pi)) * (14.0 * th).sin()
        + (65.0 / (29716.0 * pi)) * (16.0 * th).sin()
        + (208.0 / (334305.0 * pi)) * (18.0 * th).sin()
        + (28.0 / (185725.0 * pi)) * (20.0 * th).sin()
        + (112.0 / (3677355.0 * pi)) * (22.0 * th).sin()
        + (1.0 / (200583.0 * pi)) * (24.0 * th).sin()
        + (16.0 / (25206597.0 * pi)) * (26.0 * th).sin()
        + (4.0 / (67863915.0 * pi)) * (28.0 * th).sin()
        + (16.0 / (4508102925.0 * pi)) * (30.0 * th).sin()
        + (1.0 / (9617286240.0 * pi)) * (32.0 * th).sin())
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c32(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos32(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c32(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos32_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos32(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c32(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos32_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos32(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c32(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos32_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos32(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c32(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos32_cdf(kk, loc, scale);
    let hi = cos32_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
